      "mainEntity": [
        {
          "@type": "Question",
          "name": "What certifications and standards do you support?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS uses documented processes informed by NIST SP 800-88 for media sanitization and supports electronics recycling projects that require auditable handling. For regulated Bakersfield organizations, documentation can support internal controls, HIPAA-related safeguards, and equipment disposition records. Organizations remain responsible for determining their own regulatory obligations."
          }
        },
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS serves Bakersfield and Kern County organizations, including operations across the broader Central Valley. Scheduled pickup availability depends on equipment volume, loading access, project scope, equipment categories, and coordination requirements. Organizations can share equipment lists, preferred pickup windows, access details, and documentation requirements for project review."
          }
        },
        {
          "@type": "Question",
          "name": "How long does pickup take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup timing depends on equipment volume, loading access, and project service requirements. Bakersfield organizations can begin by sharing an equipment list and preferred timing, then STS can confirm a practical pickup plan. Larger cleanouts, secured spaces, building access rules, and dock scheduling may require additional coordination."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide audit documentation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS provides documentation based on the services selected and equipment handled, helping organizations maintain clear internal disposition records. Chain-of-custody records, asset reporting, and destruction documentation can support governance, procurement, sustainability, and audit workflows. Documentation needs can be identified during project planning."
          }
        }
      ]
